begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('ba24b000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer,org integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated','org_id',pg_temp.id(org))::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'demand-population-'||n||'@test.local' from generate_series(10,16) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'demand-population-a','Population A'),(pg_temp.id(2),'demand-population-b','Population B');
insert into public.memberships(organization_id,user_id,role) values
 (pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'viewer'),(pg_temp.id(1),pg_temp.id(12),'branch_user'),
 (pg_temp.id(2),pg_temp.id(13),'owner'),(pg_temp.id(1),pg_temp.id(14),'planner'),(pg_temp.id(1),pg_temp.id(15),'approver'),(pg_temp.id(1),pg_temp.id(16),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone)
 select pg_temp.id(20+n),pg_temp.id(case when n=2 then 2 else 1 end),'L'||n,'Location','branch','SA','Asia/Riyadh' from generate_series(0,2) n;
insert into public.items(id,organization_id,code,name_en,product_group,unit_of_measure,unit_cost,currency)
 values(pg_temp.id(30),pg_temp.id(1),'P1','Part','Test','EA',1,'SAR');
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(21));
create temporary table fixture(population jsonb,dataset uuid,input jsonb,report jsonb,saved uuid);
insert into fixture(population) values('{"item_code":"P1","location_code":"L0","dataset_name":"Equipment population","unit":"EA","source":"Synthetic evidence","as_of":"2026-01-02","available_on":"2026-01-03","confirmed":true,"non_overlapping":true,"rows":[{"group_code":"A","group_name":"Known","installed_on":"2026-01-01","active_assets":"12","parts_per_asset":"2.5"},{"group_code":"B","group_name":"Unknown","installed_on":null,"active_assets":"3","parts_per_asset":"0.001"},{"group_code":"C","group_name":"Zero","installed_on":null,"active_assets":"0","parts_per_asset":"1"}]}');
grant all on fixture to authenticated;
select pg_temp.login(10,1); set local role authenticated;
update fixture set dataset=public.installed_base_save(pg_temp.id(1),population,pg_temp.id(39),public.installed_base_preview(pg_temp.id(1),population)->>'fingerprint');
update fixture set input=jsonb_build_object('dataset_id',dataset,'scenario_name','Replacement demand','cutoff','2026-01-03','horizon_days',28,'confirmed',true,'rates','[{"group_code":"A","daily_rate":"0.01","source":"Explicit rate A","available_on":"2026-01-03"},{"group_code":"B","daily_rate":"0.000000001","source":"Explicit rate B","available_on":"2026-01-02"},{"group_code":"C","daily_rate":"0","source":"Explicit zero","available_on":"2026-01-01"}]'::jsonb);
create function pg_temp.preview(overrides jsonb default '{}') returns jsonb language sql as $$select public.installed_base_demand_preview(pg_temp.id(1),input||overrides) from fixture$$;
create function pg_temp.save(n integer default 40,overrides jsonb default '{}',fingerprint text default null) returns uuid language sql as $$select public.installed_base_demand_save(pg_temp.id(1),input||overrides,pg_temp.id(n),coalesce(fingerprint,report->>'fingerprint')) from fixture$$;
update fixture set report=pg_temp.preview();
select is((select report->>'daily_demand' from fixture),'0.300000000003','daily sum retains twelve decimal places');
select is((select report->>'total_demand' from fixture),'8.400000000084','horizon sum exact, without order rounding');
select is((select report#>>'{groups,0,daily_demand}' from fixture),'0.3','30 installed units times 0.01');
select is((select report#>>'{groups,1,daily_demand}' from fixture),'0.000000000003','tiny rate product retained');
select is((select report#>>'{groups,2,total_demand}' from fixture),'0','explicit zero produces zero');
select is((select report#>'{groups,1,age_days}' from fixture),'null'::jsonb,'unknown age remains unknown');
select is((select report#>'{source,population,input}' from fixture),(select public.installed_base_preview(pg_temp.id(1),population)->'input' from fixture),'full source population copied');
select is((select report#>>'{source,population_imported_at}' from fixture),(select to_jsonb(created_at)#>>'{}' from public.installed_base_datasets where organization_id=pg_temp.id(1)),'source server time separate from declared availability');
select is((select jsonb_array_length(report->'days') from fixture),28,'one row per day');
select is((select report#>>'{days,0,date}' from fixture),'2026-01-04','starts after cutoff');
select is((select report#>>'{days,27,date}' from fixture),'2026-01-31','ends after 28 calendar days');
select ok((select bool_and(d.value->>'expected_demand'=report->>'daily_demand') from fixture,jsonb_array_elements(report->'days') d),'constant daily mean');
select is(pg_temp.preview('{"horizon_days":1}')#>>'{days,0,date}','2026-01-04','one-day horizon');
select is(pg_temp.preview('{"horizon_days":90}')->>'total_demand','27.00000000027','90-day horizon exact');
select is(pg_temp.preview('{"confirmed":false}')#>'{input,confirmed}','false'::jsonb,'preview without confirmation');
select throws_ok($$select pg_temp.save(40,'{"confirmed":false}')$$,'MQ422','invalid demand scenario save','saving requires applicability');
select throws_ok($$select pg_temp.preview('{"cutoff":"2026-01-02","rates":[{"group_code":"A","daily_rate":"1","source":"s","available_on":"2026-01-02"}]}')$$,'MQ422','population unavailable by cutoff','population availability gates cutoff');
select throws_ok($$select pg_temp.preview('{"cutoff":"9999-01-01"}')$$,'MQ422','population unavailable by cutoff','future planning cutoff rejected');
select throws_ok($$select pg_temp.preview('{"horizon_days":0}')$$,'MQ422','invalid demand scenario bounds','zero horizon rejected');
select throws_ok($$select pg_temp.preview('{"horizon_days":91}')$$,'MQ422','invalid demand scenario bounds','long horizon rejected');
select throws_ok($$select pg_temp.preview('{"horizon_days":1.5}')$$,'MQ422','invalid demand scenario input','fractional horizon rejected');
select throws_ok($$select pg_temp.preview('{"cutoff":"2026-02-30"}')$$,'MQ422','invalid demand scenario dates','invalid cutoff rejected');
select throws_ok($$select pg_temp.preview('{"cutoff":"0000-01-01"}')$$,'MQ422','invalid demand scenario dates','year zero rejected');
select throws_ok($$select pg_temp.preview('{"rates":[]}')$$,'MQ422','invalid demand scenario bounds','missing rates rejected');
select throws_ok($$select pg_temp.preview(jsonb_build_object('rates',(input->'rates')-2)) from fixture$$,'MQ422','every population group requires an explicit rate','zero-asset group still requires a rate');
select throws_ok($$select pg_temp.preview(jsonb_build_object('rates',jsonb_set(input->'rates','{2,group_code}','"OTHER"'))) from fixture$$,'MQ422','every population group requires an explicit rate','unknown group rejected');
select throws_ok($$select pg_temp.preview(jsonb_build_object('rates',jsonb_set(input->'rates','{2,group_code}','" A "'))) from fixture$$,'MQ422','duplicate rate group','trimmed duplicate rejected');
select throws_ok($$select pg_temp.preview(jsonb_build_object('rates',jsonb_set(input->'rates','{0,available_on}','"2026-01-04"'))) from fixture$$,'MQ422','rate unavailable by cutoff','future rate rejected');
select throws_ok($$select pg_temp.preview(jsonb_build_object('rates',jsonb_set(input->'rates','{0,available_on}','"2026-02-30"'))) from fixture$$,'MQ422','invalid replacement rate date','invalid rate date rejected');
select throws_ok(format('select pg_temp.preview(jsonb_build_object(''rates'',jsonb_set(input->''rates'',''{0,daily_rate}'',%L::jsonb))) from fixture',to_jsonb(v)::text),'MQ422','invalid replacement rate','invalid rate: '||v)
 from unnest(array['','-1','1e-9','NaN','Infinity','1000000','0.0000000001']) v;
select throws_ok($$select pg_temp.preview(jsonb_build_object('rates',jsonb_set(input->'rates','{0,daily_rate}','0'))) from fixture$$,'MQ422','invalid replacement rate','rate must be an exact string');
select throws_ok($$select pg_temp.preview(jsonb_build_object('rates',jsonb_set(input->'rates','{0,source}','" "'))) from fixture$$,'MQ422','invalid replacement rate','source reason required');
select throws_ok($$select pg_temp.preview(jsonb_build_object('scenario_name',repeat('x',525000)))$$,'MQ422','invalid demand scenario input','payload bytes bounded');
update fixture set saved=pg_temp.save();
select is(pg_temp.save(),(select saved from fixture),'identical retry stable');
select is(pg_temp.save(40,jsonb_build_object('rates',jsonb_build_array(input#>'{rates,2}',input#>'{rates,1}',input#>'{rates,0}'))),(select saved from fixture),'rate order independent retry') from fixture;
select is(pg_temp.save(40,jsonb_build_object('rates',jsonb_set(input->'rates','{0,daily_rate}','"000000.010000000"'))),(select saved from fixture),'equivalent decimals retry canonically') from fixture;
select throws_ok($$select pg_temp.save(40,'{"scenario_name":"Changed"}')$$,'MQ409','demand scenario request conflicts','changed retry rejected');
select throws_ok($$select pg_temp.save(41,'{}',repeat('a',64))$$,'MQ409','demand scenario evidence changed; refresh preview','stale or forged preview rejected');
select is((select count(*)::integer from public.installed_base_demand_scenarios where organization_id=pg_temp.id(1)),1,'only one scenario saved');
select throws_ok($$insert into public.installed_base_demand_scenarios default values$$,'42501',null,'raw inserts denied');
select throws_ok($$update public.installed_base_demand_scenarios set scenario_name='x'$$,'42501',null,'raw updates denied');
select throws_ok($$delete from public.installed_base_demand_scenarios$$,'42501',null,'raw deletion denied');
select throws_ok($$select app.installed_base_demand_input('{}')$$,'42501',null,'normalizer private');
select pg_temp.login(11,1);
select is((select count(*)::integer from public.installed_base_demand_scenarios where organization_id=pg_temp.id(1)),1,'viewer reads');
select throws_ok($$select pg_temp.save()$$,'MQ403','demand scenario save forbidden','viewer cannot retry');
select pg_temp.login(15,1);
select throws_ok($$select pg_temp.save()$$,'MQ403','demand scenario save forbidden','approver cannot save');
select pg_temp.login(12,1);
select is((select count(*)::integer from public.installed_base_demand_scenarios where organization_id=pg_temp.id(1)),0,'other branch cannot read');
select throws_ok($$select pg_temp.preview()$$,'MQ404','population source unavailable','definer enforces branch scope');
reset role;
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(20));
set local role authenticated;
select is((select count(*)::integer from public.installed_base_demand_scenarios where organization_id=pg_temp.id(1)),1,'authorized branch reads');
select pg_temp.login(13,2);
select is((select count(*)::integer from public.installed_base_demand_scenarios where organization_id=pg_temp.id(1)),0,'other tenant cannot read');
select throws_ok($$select pg_temp.preview()$$,'MQ404','population source unavailable','other tenant cannot preview');
select pg_temp.login(10,2);
select is((select count(*)::integer from public.installed_base_demand_scenarios where organization_id=pg_temp.id(1)),0,'wrong host claim hides scenario');
select pg_temp.login(14,1);
select throws_ok($$select pg_temp.save()$$,'MQ409','demand scenario request conflicts','different author cannot reuse request');
select lives_ok($$select pg_temp.save(42)$$,'planner saves independent scenario');
select pg_temp.login(16,1);
select lives_ok($$select pg_temp.save(43)$$,'admin saves independent scenario');
reset role;
select is((select count(*)::integer from public.audit_log where organization_id=pg_temp.id(1) and table_name='installed_base_demand_scenarios'),3,'exactly one audit per save');
update public.items set unit_of_measure='SET',name_en='Changed' where id=pg_temp.id(30);
select pg_temp.login(10,1); set local role authenticated;
select is(pg_temp.preview()->>'fingerprint',(select report->>'fingerprint' from fixture),'captured population is fixed after catalog changes');
select is(pg_temp.save(),(select saved from fixture),'retry preserves captured evidence');
reset role;
delete from public.installed_base_datasets where organization_id=pg_temp.id(1);
delete from public.items where id=pg_temp.id(30);
set local role authenticated;
select is((select report from public.installed_base_demand_scenarios where id=(select saved from fixture)),(select report from fixture),'copied scenario survives dataset and part deletion');
select is(pg_temp.save(),(select saved from fixture),'retry uses retained evidence after source deletion');
select throws_ok($$select pg_temp.save(44)$$,'MQ404','population source unavailable','new save requires visible source');
reset role;
select is((select count(*)::integer from public.planning_runs where organization_id=pg_temp.id(1)),0,'no planning runs created');
select is((select count(*)::integer from public.stock_snapshots where organization_id=pg_temp.id(1)),0,'no stock changes');
delete from public.locations where id=pg_temp.id(20);
select is((select count(*)::integer from public.installed_base_demand_scenarios where organization_id=pg_temp.id(1)),0,'location cascade retained');
select * from finish();
rollback;
